class InstanceLockError(Exception):
    """Une autre instance du broker detient deja le verrou exclusif."""


def utc_now():
    return (
        datetime.now(timezone.utc)
        .isoformat()
        .replace("+00:00", "Z")
    )


def utc_from_timestamp(timestamp):
    return (
        datetime.fromtimestamp(
            timestamp,
            tz=timezone.utc,
        )
        .isoformat()
        .replace("+00:00", "Z")
    )


def parse_utc(value):
    if (
        not value
        or not isinstance(value, str)
    ):
        return None

    try:
        return datetime.fromisoformat(
            value.replace(
                "Z",
                "+00:00",
            )
        ).timestamp()

    except ValueError:
        return None


def instance_lock_path():
    """Retourne le verrou exclusif de l'instance broker."""
    return os.environ.get(
        "CGPT_BROKER_INSTANCE_LOCK",
        DEFAULT_INSTANCE_LOCK,
    )


def new_instance_id():
    """Genere un identifiant unique pour le processus broker."""
    return (
        "inst-"
        + uuid.uuid4().hex
    )


def read_instance_lock_metadata(handle):
    """Lit les metadonnees presentes dans le fichier de verrou."""
    try:
        handle.seek(0)
        raw = handle.read()
    except OSError:
        return {}

    if not raw.strip():
        return {}

    try:
        value = json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        return {
            "raw": raw[:500],
        }

    return value if isinstance(value, dict) else {}


def acquire_instance_lock():
    """Acquiert le verrou exclusif conserve pendant toute la vie du broker."""
    global INSTANCE_ID
    global INSTANCE_LOCK_HANDLE
    global INSTANCE_LOCK_METADATA
    global INSTANCE_PREVIOUS_METADATA

    path = instance_lock_path()
    ensure_parent(path)

    try:
        handle = open(
            path,
            "a+",
            encoding="utf-8",
        )
    except OSError as exc:
        raise InstanceLockError(
            "ouverture verrou instance impossible: %s"
            % exc
        ) from exc

    previous_metadata = read_instance_lock_metadata(
        handle
    )

    try:
        fcntl.flock(
            handle.fileno(),
            fcntl.LOCK_EX | fcntl.LOCK_NB,
        )
    except BlockingIOError as exc:
        owner = read_instance_lock_metadata(
            handle
        )
        handle.close()

        owner_id = owner.get(
            "instance_id",
            "inconnu",
        )
        owner_pid = owner.get(
            "pid",
            "inconnu",
        )
        owner_host = owner.get(
            "hostname",
            "inconnu",
        )

        raise InstanceLockError(
            "broker deja actif: instance_id=%s pid=%s hostname=%s lock=%s"
            % (
                owner_id,
                owner_pid,
                owner_host,
                path,
            )
        ) from exc
    except OSError as exc:
        handle.close()
        raise InstanceLockError(
            "verrouillage instance impossible: %s"
            % exc
        ) from exc

    INSTANCE_ID = new_instance_id()
    metadata = {
        "instance_id": INSTANCE_ID,
        "pid": os.getpid(),
        "hostname": socket.gethostname(),
        "started_at": PROCESS_STARTED_AT,
        "server_name": SERVER_NAME,
        "server_version": SERVER_VERSION,
        "lock_path": path,
    }

    try:
        handle.seek(0)
        handle.truncate(0)
        json.dump(
            metadata,
            handle,
            ensure_ascii=False,
            indent=2,
        )
        handle.write("\n")
        handle.flush()
        os.fsync(
            handle.fileno()
        )
    except OSError as exc:
        try:
            fcntl.flock(
                handle.fileno(),
                fcntl.LOCK_UN,
            )
        except OSError:
            pass
        handle.close()
        raise InstanceLockError(
            "ecriture metadonnees instance impossible: %s"
            % exc
        ) from exc

    INSTANCE_LOCK_HANDLE = handle
    INSTANCE_LOCK_METADATA = metadata
    INSTANCE_PREVIOUS_METADATA = (
        previous_metadata
        if isinstance(previous_metadata, dict)
        else {}
    )

    return dict(metadata)




def previous_instance_shutdown_state(previous_id):
    """Determine si la derniere execution connue s'est terminee proprement."""
    if not previous_id:
        return "UNKNOWN"

    try:
        events = journal.read_events()
    except (journal.JournalError, journal.JournalValidationError):
        return "UNKNOWN"

    started_sequence = None
    stopping_sequence = None
    stopped_sequence = None

    for event in events:
        data = event.get("data", {})

        if not isinstance(data, dict):
            continue

        if data.get("instance_id") != previous_id:
            continue

        event_type = event.get("event_type")
        sequence = event.get("sequence")

        if event_type == "BROKER_INSTANCE_STARTED":
            started_sequence = sequence
            stopping_sequence = None
            stopped_sequence = None

        elif (
            event_type == "BROKER_INSTANCE_STOPPING"
            and started_sequence is not None
            and sequence > started_sequence
        ):
            stopping_sequence = sequence

        elif (
            event_type == "BROKER_INSTANCE_STOPPED"
            and started_sequence is not None
            and sequence > started_sequence
        ):
            stopped_sequence = sequence

    if started_sequence is None:
        return "UNKNOWN"

    if stopped_sequence is not None:
        return "CLEAN"

    return "UNCLEAN"

def instance_lifecycle_event(
    event_type,
    phase,
    data=None,
):
    """Journalise une etape du cycle de vie de cette instance."""
    if not INSTANCE_ID:
        return None

    payload = {
        "instance_id": INSTANCE_ID,
        "pid": os.getpid(),
        "hostname": socket.gethostname(),
        "started_at": PROCESS_STARTED_AT,
        "server_version": SERVER_VERSION,
        "lock_path": instance_lock_path(),
    }

    if data:
        payload.update(data)

    return journal.append_unique_event(
        event_type=event_type,
        event_key=(
            "broker-instance:%s:%s"
            % (INSTANCE_ID, phase)
        ),
        actor="BROKER",
        data=payload,
    )


def journal_instance_started():
    """Journalise la prise de possession effective du verrou."""
    global INSTANCE_PREVIOUS_SHUTDOWN_STATE

    previous = INSTANCE_PREVIOUS_METADATA

    previous_id = (
        previous.get("instance_id", "")
        if isinstance(previous, dict)
        else ""
    )

    INSTANCE_PREVIOUS_SHUTDOWN_STATE = (
        previous_instance_shutdown_state(previous_id)
    )

    if previous_id and previous_id != INSTANCE_ID:
        if INSTANCE_PREVIOUS_SHUTDOWN_STATE == "UNCLEAN":
            instance_lifecycle_event(
                "BROKER_INSTANCE_UNCLEAN_SHUTDOWN_DETECTED",
                "unclean-shutdown-detected",
                {
                    "previous_instance": {
                        "instance_id": previous.get("instance_id", ""),
                        "pid": previous.get("pid"),
                        "hostname": previous.get("hostname", ""),
                        "started_at": previous.get("started_at", ""),
                        "server_version": previous.get("server_version", ""),
                    },
                    "previous_shutdown_state": (
                        INSTANCE_PREVIOUS_SHUTDOWN_STATE
                    ),
                    "detected_at": utc_now(),
                },
            )

        instance_lifecycle_event(
            "BROKER_INSTANCE_RECOVERED_STALE_METADATA",
            "recovered-stale-metadata",
            {
                "previous_instance": {
                    "instance_id": previous.get("instance_id", ""),
                    "pid": previous.get("pid"),
                    "hostname": previous.get("hostname", ""),
                    "started_at": previous.get("started_at", ""),
                    "server_version": previous.get("server_version", ""),
                },
                "previous_shutdown_state": (
                    INSTANCE_PREVIOUS_SHUTDOWN_STATE
                ),
            },
        )

    return instance_lifecycle_event(
        "BROKER_INSTANCE_STARTED",
        "started",
        {
            "previous_shutdown_state": (
                INSTANCE_PREVIOUS_SHUTDOWN_STATE
            ),
        },
    )


def journal_instance_stopping(reason="stdio_closed"):
    """Journalise le debut d'un arret propre."""
    return instance_lifecycle_event(
        "BROKER_INSTANCE_STOPPING",
        "stopping",
        {
            "reason": reason,
            "stopping_at": utc_now(),
        },
    )


def journal_instance_stopped(reason="stdio_closed"):
    """Journalise la fin d'un arret propre avant liberation du verrou."""
    return instance_lifecycle_event(
        "BROKER_INSTANCE_STOPPED",
        "stopped",
        {
            "reason": reason,
            "stopped_at": utc_now(),
        },
    )


def release_instance_lock():
    """Libere explicitement le verrou d'instance a l'arret normal."""
    global INSTANCE_LOCK_HANDLE

    handle = INSTANCE_LOCK_HANDLE
    INSTANCE_LOCK_HANDLE = None

    if handle is None:
        return

    try:
        fcntl.flock(
            handle.fileno(),
            fcntl.LOCK_UN,
        )
    except OSError:
        pass

    try:
        handle.close()
    except OSError:
        pass


def instance_snapshot():
    """Expose uniquement les metadonnees non sensibles de l'instance."""
    return {
        "instance_id": INSTANCE_ID,
        "exclusive_lock": (
            INSTANCE_LOCK_HANDLE is not None
        ),
        "lock_path": instance_lock_path(),
        "pid": os.getpid(),
        "hostname": socket.gethostname(),
        "started_at": PROCESS_STARTED_AT,
        "previous_instance_id": (
            INSTANCE_PREVIOUS_METADATA.get(
                "instance_id",
                "",
            )
            if isinstance(
                INSTANCE_PREVIOUS_METADATA,
                dict,
            )
            else ""
        ),
        "previous_shutdown_state": (
            INSTANCE_PREVIOUS_SHUTDOWN_STATE
        ),
        "crash_recovery": dict(CRASH_RECOVERY_REPORT),
    }



def journal_crash_recovery_event(event_type, recovery_id, phase, data=None):
    """Journalise une etape idempotente de recuperation post-crash."""
    payload = {
        "recovery_id": recovery_id,
        "instance_id": INSTANCE_ID,
        "previous_instance_id": (
            INSTANCE_PREVIOUS_METADATA.get("instance_id", "")
            if isinstance(INSTANCE_PREVIOUS_METADATA, dict)
            else ""
        ),
        "previous_shutdown_state": INSTANCE_PREVIOUS_SHUTDOWN_STATE,
    }
    if data:
        payload.update(data)
    return journal.append_unique_event(
        event_type=event_type,
        event_key="broker-crash-recovery:%s:%s" % (recovery_id, phase),
        actor="BROKER",
        data=payload,
    )


def recover_after_unclean_shutdown():
    """Inspecte et repare uniquement les etats techniques non ambigus apres crash."""
    global CRASH_RECOVERY_REPORT

    if INSTANCE_PREVIOUS_SHUTDOWN_STATE != "UNCLEAN":
        CRASH_RECOVERY_REPORT = {
            "status": "NOT_REQUIRED",
            "performed": False,
            "human_required": False,
        }
        return dict(CRASH_RECOVERY_REPORT)

    recovery_id = "recovery-" + uuid.uuid4().hex[:16]
    started_at = utc_now()
    journal_crash_recovery_event(
        "BROKER_CRASH_RECOVERY_STARTED",
        recovery_id,
        "started",
        {"started_at": started_at},
    )

    path = store_path()
    pending_ids = []
    recovered_leases = []
    expired_ids = []

    with locked_store(path):
        data = load_store(path)
        approvals = data["approvals"]
        changed = False

        for item in approvals.values():
            approval_id = item.get("approval_id", "")

            if check_expired(item):
                changed = True
                if approval_id:
                    expired_ids.append(approval_id)

            if (
                item.get("status") == "PENDING"
                and item.get("notification_status") == "SENDING"
            ):
                recovered_leases.append({
                    "approval_id": approval_id,
                    "lease_id": item.get("notification_lease_id", ""),
                })
                item["notification_status"] = "FAILED"
                item["notification_lease_id"] = ""
                item["notification_lease_until"] = ""
                item["notification_next_retry_at"] = ""
                item["notification_updated_at"] = utc_now()
                changed = True

            if item.get("status") == "PENDING" and approval_id:
                pending_ids.append(approval_id)

        if changed:
            save_store(path, data)

        event_index = {
            (event.get("approval_id", ""), event.get("event_type", ""))
            for event in journal.read_events()
        }
        for item in approvals.values():
            repair_journal_for_item(item, event_index=event_index)

    consistency_before = store_journal_consistency_snapshot()
    repair_result = None
    if (
        consistency_before.get("missing_created_events")
        or consistency_before.get("missing_terminal_events")
    ):
        repair_result = do_repair_consistency()

    consistency_after = store_journal_consistency_snapshot()
    human_required = not consistency_after.get("ok", False)

    resumed_decisions = []
    renotified_approvals = []
    still_pending = []

    # Reprise active uniquement si la coherence store/journal est sure.
    # On recherche d'abord une decision deja detenue par le controleur.
    # Une nouvelle notification n'est envoyee qu'en l'absence de decision.
    if not human_required:
        for approval_id in list(pending_ids):
            with locked_store(path):
                current_data = load_store(path)
                current = current_data["approvals"].get(approval_id)

                if (
                    current is None
                    or current.get("status") != "PENDING"
                ):
                    continue

                snapshot = dict(current)

            decision = controller_decision(snapshot)

            if decision is not None:
                applied = False

                with locked_store(path):
                    current_data = load_store(path)
                    current = current_data["approvals"].get(approval_id)

                    if (
                        current is not None
                        and current.get("status") == "PENDING"
                        and apply_controller_decision(current, decision)
                    ):
                        current["recovered_after_crash_at"] = utc_now()
                        current["recovery_id"] = recovery_id
                        save_store(path, current_data)
                        repair_journal_for_item(current)
                        applied = True

                if applied:
                    resumed_decisions.append(approval_id)
                    journal.append_unique_event(
                        event_type=(
                            "BROKER_CRASH_RECOVERY_DECISION_APPLIED"
                        ),
                        event_key=(
                            "broker-crash-recovery:%s:decision:%s"
                            % (recovery_id, approval_id)
                        ),
                        actor="BROKER",
                        approval_id=approval_id,
                        request_id=snapshot.get("requestId", ""),
                        change_id=snapshot.get("change_id", ""),
                        data={
                            "recovery_id": recovery_id,
                            "decision": decision.get("decision", ""),
                            "decision_id": decision.get("decision_id", ""),
                        },
                    )
                    continue

            # Aucune decision exploitable : remettre le cycle de notification
            # en marche. maybe_notify_controller() gere lui-meme lease/backoff.
            if maybe_notify_controller(snapshot):
                renotified_approvals.append(approval_id)
                journal.append_unique_event(
                    event_type="BROKER_CRASH_RECOVERY_RENOTIFIED",
                    event_key=(
                        "broker-crash-recovery:%s:renotify:%s"
                        % (recovery_id, approval_id)
                    ),
                    actor="BROKER",
                    approval_id=approval_id,
                    request_id=snapshot.get("requestId", ""),
                    change_id=snapshot.get("change_id", ""),
                    data={
                        "recovery_id": recovery_id,
                        "notification_delivered": True,
                    },
                )

            with locked_store(path):
                current_data = load_store(path)
                current = current_data["approvals"].get(approval_id)
                if (
                    current is not None
                    and current.get("status") == "PENDING"
                ):
                    still_pending.append(approval_id)
    else:
        still_pending = list(pending_ids)

    for recovered in recovered_leases:
        journal.append_unique_event(
            event_type="BROKER_CRASH_RECOVERY_LEASE_RESET",
            event_key=(
                "broker-crash-recovery:%s:lease:%s"
                % (recovery_id, recovered.get("approval_id", ""))
            ),
            actor="BROKER",
            approval_id=recovered.get("approval_id", ""),
            data={
                "recovery_id": recovery_id,
                "previous_lease_id": recovered.get("lease_id", ""),
                "notification_status": "FAILED",
            },
        )

    status = "HUMAN_REQUIRED" if human_required else "RECOVERED"
    report = {
        "status": status,
        "performed": True,
        "recovery_id": recovery_id,
        "started_at": started_at,
        "completed_at": utc_now(),
        "pending_approvals": still_pending,
        "pending_count": len(still_pending),
        "initial_pending_count": len(pending_ids),
        "resumed_decisions": resumed_decisions,
        "resumed_decision_count": len(resumed_decisions),
        "renotified_approvals": renotified_approvals,
        "renotified_count": len(renotified_approvals),
        "recovered_notification_leases": len(recovered_leases),
        "expired_approvals": expired_ids,
        "consistency_ok": consistency_after.get("ok", False),
        "consistency": consistency_after,
        "repair_result": repair_result,
        "human_required": human_required,
    }

    journal_crash_recovery_event(
        "BROKER_CRASH_RECOVERY_COMPLETED",
        recovery_id,
        "completed",
        {
            "status": status,
            "pending_count": len(still_pending),
            "initial_pending_count": len(pending_ids),
            "resumed_decision_count": len(resumed_decisions),
            "renotified_count": len(renotified_approvals),
            "recovered_notification_leases": len(recovered_leases),
            "expired_count": len(expired_ids),
            "consistency_ok": consistency_after.get("ok", False),
            "human_required": human_required,
        },
    )

    CRASH_RECOVERY_REPORT = report
    return dict(report)

def new_approval_id():
    return (
        "apr-"
        + uuid.uuid4().hex[:16]
    )


def new_business_request_id():
    return (
        "req-"
        + uuid.uuid4().hex[:16]
    )


def new_store():
    return {
        "schema_version": STORE_SCHEMA_VERSION,
        "approvals": {},
    }


def store_path():
    return os.environ.get(
        "CGPT_APPROVAL_STORE",
        DEFAULT_STORE,
    )


def store_lock_path(path):
    return path + ".lock"


def ensure_parent(path):
    parent = os.path.dirname(path)

    if parent:
        os.makedirs(
            parent,
            exist_ok=True,
        )


@contextmanager
def locked_store(path):
    ensure_parent(path)

    lock_path = store_lock_path(
        path
    )

    with THREAD_STORE_LOCK:
        try:
            lock_handle = open(
                lock_path,
                "a+",
                encoding="utf-8",
            )

        except OSError as exc:
            raise StoreError(
                "ouverture verrou magasin impossible: %s"
                % exc
            ) from exc

        try:
            try:
                fcntl.flock(
                    lock_handle.fileno(),
                    fcntl.LOCK_EX,
                )

            except OSError as exc:
                raise StoreError(
                    "verrouillage magasin impossible: %s"
                    % exc
                ) from exc

            yield

        finally:
            try:
                fcntl.flock(
                    lock_handle.fileno(),
                    fcntl.LOCK_UN,
                )

            except OSError:
                pass

            lock_handle.close()


def raw_load_store(path):
    try:
        with open(
            path,
            "r",
            encoding="utf-8",
        ) as handle:
            return json.load(
                handle
            )

    except FileNotFoundError:
        return new_store()

    except (
        json.JSONDecodeError,
        OSError,
    ) as exc:
        raise StoreError(
            "magasin illisible: %s"
            % exc
        ) from exc


def normalize_legacy_request_ids(item):
    legacy = item.get(
        "legacy_requestIds",
        [],
    )

    if legacy is None:
        legacy = []

    if not isinstance(
        legacy,
        list,
    ):
        raise StoreError(
            "legacy_requestIds doit etre une liste"
        )

    result = []

    for value in legacy:
        if (
            isinstance(value, str)
            and value
            and value not in result
        ):
            result.append(
                value
            )

    item[
        "legacy_requestIds"
    ] = result

    return result


def migrate_store_v1_to_v2(data):
    approvals = data.get(
        "approvals"
    )

    if not isinstance(
        approvals,
        dict,
    ):
        raise StoreError(
            "magasin v1 corrompu: approvals absent"
        )

    for key, item in approvals.items():
        if not isinstance(
            item,
            dict,
        ):
            raise StoreError(
                "approbation '%s' invalide"
                % key
            )

        approval_id = item.get(
            "approval_id"
        )

        if not approval_id:
            approval_id = key

            item[
                "approval_id"
            ] = approval_id

        legacy = normalize_legacy_request_ids(
            item
        )

        request_id = item.get(
            "requestId"
        )

        if (
            not isinstance(
                request_id,
                str,
            )
            or not request_id
        ):
            item[
                "requestId"
            ] = new_business_request_id()

        elif request_id == approval_id:
            if request_id not in legacy:
                legacy.append(
                    request_id
                )

            item[
                "requestId"
            ] = new_business_request_id()

        item[
            "legacy_requestIds"
        ] = legacy

        item[
            "store_migrated_from"
        ] = 1

        item[
            "store_migrated_at"
        ] = utc_now()

    data[
        "schema_version"
    ] = 2

    return data


def migrate_store(data):
    if not isinstance(
        data,
        dict,
    ):
        raise StoreError(
            "magasin corrompu: objet JSON attendu"
        )

    approvals = data.get(
        "approvals"
    )

    if not isinstance(
        approvals,
        dict,
    ):
        raise StoreError(
            "magasin corrompu: approvals invalide"
        )

    version = data.get(
        "schema_version"
    )

    if version is None:
        version = 1

    if (
        not isinstance(
            version,
            int,
        )
        or isinstance(
            version,
            bool,
        )
    ):
        raise StoreError(
            "schema_version invalide"
        )

    if version > STORE_SCHEMA_VERSION:
        raise StoreError(
            "schema magasin trop recent : %s > %s"
            % (
                version,
                STORE_SCHEMA_VERSION,
            )
        )

    migrated = False

    while version < STORE_SCHEMA_VERSION:
        if version == 1:
            data = migrate_store_v1_to_v2(
                data
            )

            version = 2
            migrated = True

        else:
            raise StoreError(
                "migration inconnue depuis schema %s"
                % version
            )

    for item in data[
        "approvals"
    ].values():
        normalize_legacy_request_ids(
            item
        )

    data[
        "schema_version"
    ] = STORE_SCHEMA_VERSION

    return (
        data,
        migrated,
    )


def fsync_directory(path):
    directory = os.path.dirname(
        path
    )

    if not directory:
        directory = "."

    flags = os.O_RDONLY

    if hasattr(
        os,
        "O_DIRECTORY",
    ):
        flags |= os.O_DIRECTORY

    try:
        directory_fd = os.open(
            directory,
            flags,
        )

    except OSError as exc:
        raise StoreError(
            "ouverture repertoire pour fsync impossible: %s"
            % exc
        ) from exc

    try:
        os.fsync(
            directory_fd
        )

    except OSError as exc:
        raise StoreError(
            "fsync repertoire impossible: %s"
            % exc
        ) from exc

    finally:
        os.close(
            directory_fd
        )


def save_store(
    path,
    data,
):
    """Ecrit atomiquement et durablement le magasin."""
    ensure_parent(
        path
    )

    data[
        "schema_version"
    ] = STORE_SCHEMA_VERSION

    tmp_path = (
        path
        + ".tmp."
        + str(os.getpid())
        + "."
        + str(threading.get_ident())
    )

    replaced = False

    try:
        with open(
            tmp_path,
            "w",
            encoding="utf-8",
        ) as handle:
            json.dump(
                data,
                handle,
                ensure_ascii=False,
                indent=2,
            )

            handle.write(
                "\n"
            )

            handle.flush()

            os.fsync(
                handle.fileno()
            )

        os.replace(
            tmp_path,
            path,
        )

        replaced = True

        fsync_directory(
            path
        )

    except OSError as exc:
        raise StoreError(
            "ecriture durable magasin impossible: %s"
            % exc
        ) from exc

    finally:
        if not replaced:
            try:
                if os.path.exists(
                    tmp_path
                ):
                    os.remove(
                        tmp_path
                    )

            except OSError:
                pass


def load_store(path):
    data = raw_load_store(
        path
    )

    data, migrated = migrate_store(
        data
    )

    if migrated:
        save_store(
            path,
            data,
        )

    return data


def item_request_ids(item):
    result = []

    request_id = item.get(
        "requestId"
    )

    if (
        isinstance(
            request_id,
            str,
        )
        and request_id
    ):
        result.append(
            request_id
        )

    for value in item.get(
        "legacy_requestIds",
        [],
    ):
        if (
            isinstance(
                value,
                str,
            )
            and value
            and value not in result
        ):
            result.append(
                value
            )

    return result


def request_id_matches_item(
    item,
    request_id,
):
    if not request_id:
        return False

    return request_id in item_request_ids(
        item
    )


def find_by_request_id(
    approvals,
    request_id,
):
    if not request_id:
        return None

    matches = []

    for item in approvals.values():
        if request_id_matches_item(
            item,
            request_id,
        ):
            matches.append(
                item
            )

    if not matches:
        return None

    if len(matches) > 1:
        raise StoreError(
            "requestId '%s' correspond a plusieurs approbations"
            % request_id
        )

    return matches[
        0
    ]


def check_request_id_uniqueness(
    approvals,
):
    owners = {}

    for item in approvals.values():
        approval_id = item.get(
            "approval_id"
        )

        for request_id in item_request_ids(
            item
        ):
            previous = owners.get(
                request_id
            )

            if (
                previous is not None
                and previous != approval_id
            ):
                return (
                    False,
                    request_id,
                )

            owners[
                request_id
            ] = approval_id

    return (
        True,
        "",
    )


def journal_event_exists(
    approval_id,
    event_type,
    event_index=None,
):
    if event_index is not None:
        approval_id = journal.optional_string(
            approval_id, "approval_id", journal.MAX_IDENTIFIER_LENGTH,
        )
        event_type = journal.optional_string(
            event_type, "event_type", journal.MAX_EVENT_TYPE_LENGTH,
        )
        if approval_id and event_type:
            return (approval_id, event_type) in event_index

    events = journal.read_events(
        approval_id=approval_id,
        event_type=event_type,
        limit=1,
    )

    return bool(
        events
    )


def ensure_journal_event(
    item,
    event_type,
    actor,
    data=None,
    event_index=None,
):
    approval_id = item.get(
        "approval_id",
        "",
    )

    if not approval_id:
        raise journal.JournalValidationError(
            "approval_id absent pour journalisation"
        )

    if journal_event_exists(
        approval_id,
        event_type,
        event_index=event_index,
    ):
        return None

    payload = {
        "status": item.get(
            "status",
            "",
        ),
    }

    if data:
        payload.update(
            data
        )

    event = journal.append_event(
        event_type=event_type,
        approval_id=approval_id,
        request_id=item.get(
            "requestId",
            "",
        ),
        change_id=item.get(
            "change_id",
            "",
        ),
        actor=actor,
        data=payload,
    )

    if event_index is not None:
        event_index.add((event["approval_id"], event["event_type"]))

    return event


def ensure_created_event(item, event_index=None):
    return ensure_journal_event(
        item,
        "APPROVAL_CREATED",
        "OC",
        {
            "title": item.get(
                "title",
                "",
            ),
            "files": item.get(
                "files",
                [],
            ),
            "summary": item.get(
                "summary",
                "",
            ),
            "expires_at": item.get(
                "expires_at",
                "",
            ),
        },
        event_index=event_index,
    )


def terminal_event_actor(item):
    status = item.get(
        "status"
    )

    if status == "EXPIRED":
        return "BROKER"

    if status == "CANCELLED":
        return (
            item.get(
                "cancelled_by",
                "",
            )
            or "OC"
        )

    return (
        item.get(
            "reviewer",
            "",
        )
        or "CGPT"
    )


def terminal_event_data(item):
    status = item.get(
        "status"
    )

    payload = {
        "status": status,
    }

    if status in (
        "APPROVED",
        "REJECTED",
        "NEEDS_CLARIFICATION",
    ):
        payload.update(
            {
                "reviewer": item.get(
                    "reviewer",
                    "",
                ),
                "comment": item.get(
                    "comment",
                    "",
                ),
                "decision_id": item.get(
                    "decision_id",
                    "",
                ),
                "decision_applied_at": item.get(
                    "decision_applied_at",
                    "",
                ),
            }
        )

    elif status == "CANCELLED":
        payload.update(
            {
                "cancelled_at": item.get(
                    "cancelled_at",
                    item.get(
                        "updated_at",
                        "",
                    ),
                ),
                "cancelled_by": item.get(
                    "cancelled_by",
                    "OC",
                ),
            }
        )

    elif status == "EXPIRED":
        payload.update(
            {
                "expires_at": item.get(
                    "expires_at",
                    "",
                ),
                "expired_at": item.get(
                    "expired_at",
                    item.get(
                        "updated_at",
                        "",
                    ),
                ),
            }
        )

    return payload


def ensure_terminal_event(item, event_index=None):
    status = item.get(
        "status"
    )

    event_type = STATUS_EVENT_TYPES.get(
        status
    )

    if event_type is None:
        return None

    return ensure_journal_event(
        item,
        event_type,
        terminal_event_actor(
            item
        ),
        terminal_event_data(
            item
        ),
        event_index=event_index,
    )


def repair_journal_for_item(item, event_index=None):
    """Repare les evenements fondamentaux manquants."""
    ensure_created_event(
        item,
        event_index=event_index,
    )

    ensure_terminal_event(
        item,
        event_index=event_index,
    )


def check_expired(item):
    """Applique EXPIRED en memoire.

    La sauvegarde durable et la journalisation restent de la
    responsabilite de l'appelant.
    """
    if item.get(
        "status"
    ) != "PENDING":
        return False

    expires_timestamp = parse_utc(
        item.get(
            "expires_at"
        )
    )

    if expires_timestamp is None:
        return False

    if time.time() < expires_timestamp:
        return False

    now = utc_now()

    item[
        "status"
    ] = "EXPIRED"

    item[
        "updated_at"
    ] = now

    item[
        "expired_at"
    ] = now

    return True


def controller_url():
    return os.environ.get(
        "CGPT_CONTROLLER_URL",
        DEFAULT_CONTROLLER_URL,
    ).rstrip(
        "/"
    )


def controller_endpoint():
    parsed = parse.urlparse(
        controller_url()
    )

    hostname = parsed.hostname

    if not hostname:
        return (
            None,
            None,
        )

    if parsed.port is not None:
        port = parsed.port

    elif parsed.scheme == "https":
        port = 443

    else:
        port = 80

    return (
        hostname,
        port,
    )


def controller_tcp_reachable():
    host, port = controller_endpoint()

    if (
        host is None
        or port is None
    ):
        return False

    try:
        with socket.create_connection(
            (
                host,
                port,
            ),
            timeout=(
                CONTROLLER_TCP_TIMEOUT_SECONDS
            ),
        ):
            return True

    except OSError:
        return False


def controller_event_key(
    item,
    suffix,
    correlation_id,
):
    approval_id = item.get(
        "approval_id",
        "",
    )

    return (
        "controller:%s:%s:%s"
        % (
            approval_id,
            correlation_id,
            suffix,
        )
    )


def journal_controller_event(
    item,
    event_type,
    event_key,
    data=None,
):
    return journal.append_unique_event(
        event_type=event_type,
        event_key=event_key,
        approval_id=item.get(
            "approval_id",
            "",
        ),
        request_id=item.get(
            "requestId",
            "",
        ),
        change_id=item.get(
            "change_id",
            "",
        ),
        actor="BROKER",
        data=(
            data
            if data is not None
            else {}
        ),
    )


def controller_length_failure(exc):
    """Reconstruit uniquement le diagnostic de longueur connu, sans texte distant."""
    if exc.code != 400:
        return None
    try:
        body = exc.read(1025)
        if len(body) > 1024:
            return None
        payload = json.loads(body.decode("utf-8"))
    except (OSError, HTTPException, ValueError, UnicodeError):
        return None
    if not isinstance(payload, dict):
        return None
    maximum = payload.get("maxLength")
    actual = payload.get("actualLength")
    if (payload.get("error") != "command-too-long" or payload.get("unit") != "utf16"
            or type(maximum) is not int or type(actual) is not int
            or not 0 < maximum < actual <= 9007199254740991):
        return None
    return ("command-too-long: longueur %d, limite autorisée %d (utf16)."
            % (actual, maximum))


def notify_controller(
    item,
    lease_id,
):
    endpoint = (
        controller_url()
        + ("/validation/resource-request" if item.get("run_id") else "/validation/request")
    )

    attempted_key = controller_event_key(
        item,
        "notification-attempted",
        lease_id,
    )

    journal_controller_event(
        item,
        "CONTROLLER_NOTIFICATION_ATTEMPTED",
        attempted_key,
        {
            "lease_id": lease_id,
            "endpoint": endpoint,
        },
    )

    payload = json.dumps(
        {
            "event": "validation.request",
            "approval": item,
        },
        ensure_ascii=False,
    ).encode(
        "utf-8"
    )

    http_request = request.Request(
        endpoint,
        data=payload,
        headers={
            "Content-Type": "application/json",
        },
        method="POST",
    )

    delivered = False
    status = None
    failure = ""

    try:
        with request.urlopen(
            http_request,
            timeout=(
                CONTROLLER_HTTP_TIMEOUT_SECONDS
            ),
        ) as response:
            status = response.status
            delivered = (
                200 <= status < 300
            )

            if not delivered:
                failure = (
                    "HTTP status %s"
                    % status
                )

    except error.HTTPError as exc:
        status = exc.code
        with exc:
            failure = controller_length_failure(exc) or "HTTPError: %s" % status

    except error.URLError as exc:
        failure = (
            "URLError: %s"
            % exc.reason
        )

    except OSError as exc:
        failure = (
            "OSError: %s"
            % exc
        )

    note_session_activity("controller")

    if delivered:
        event_type = (
            "CONTROLLER_NOTIFICATION_DELIVERED"
        )

        suffix = "notification-delivered"

        event_data = {
            "lease_id": lease_id,
            "http_status": status,
        }

    else:
        event_type = (
            "CONTROLLER_NOTIFICATION_FAILED"
        )

        suffix = "notification-failed"

        event_data = {
            "lease_id": lease_id,
            "http_status": status,
            "error": failure,
        }

    journal_controller_event(
        item,
        event_type,
        controller_event_key(
            item,
            suffix,
            lease_id,
        ),
        event_data,
    )

    return {
        "delivered": delivered,
        "http_status": status,
        "error": failure,
    }


def remind_controller(item, age_seconds, last_state):
    """Relance le controleur sans modifier l'etat metier du mandat."""
    approval_id = item.get("approval_id", "")
    endpoint = controller_url() + ("/validation/resource-reminder" if item.get("run_id") else "/validation/reminder")
    payload = json.dumps(
        {
            "event": "validation.reminder",
            "approval": item,
            "age_seconds": age_seconds,
            "last_state": last_state,
        },
        ensure_ascii=False,
    ).encode("utf-8")
    bucket = int(time.time() // REMINDER_INTERVAL_SECONDS)
    journal.append_unique_event(
        event_type="CONTROLLER_REMINDER_ATTEMPTED",
        event_key="controller-reminder:%s:attempt:%s" % (approval_id, bucket),
        approval_id=approval_id,
        request_id=item.get("requestId", ""),
        change_id=item.get("change_id", ""),
        actor="BROKER",
        data={"endpoint": endpoint, "age_seconds": age_seconds, "last_state": last_state},
    )
    http_request = request.Request(
        endpoint,
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with request.urlopen(http_request, timeout=CONTROLLER_HTTP_TIMEOUT_SECONDS) as response:
            delivered = 200 <= response.status < 300
            status = response.status
    except (error.HTTPError, error.URLError, OSError):
        delivered = False
        status = None
    journal.append_unique_event(
        event_type="CONTROLLER_REMINDER_DELIVERED" if delivered else "CONTROLLER_REMINDER_FAILED",
        event_key="controller-reminder:%s:%s:%s" % (approval_id, "delivered" if delivered else "failed", bucket),
        approval_id=approval_id,
        request_id=item.get("requestId", ""),
        change_id=item.get("change_id", ""),
        actor="BROKER",
        data={"http_status": status},
    )
    return delivered


def maybe_remind_controller(item, age_seconds, last_state):
    """Reserve atomiquement une relance de trente secondes pour un PENDING."""
    approval_id = item.get("approval_id", "")
    if not approval_id or item.get("notification_status") != "DELIVERED":
        return False
    now_ts = time.time()
    path = store_path()
    with locked_store(path):
        data = load_store(path)
        current = data["approvals"].get(approval_id)
        if current is None or current.get("status") != "PENDING":
            return False
        last_reminder = parse_utc(current.get("reminder_last_at", ""))
        if last_reminder is not None and now_ts - last_reminder < REMINDER_INTERVAL_SECONDS:
            return False
        current["reminder_last_at"] = utc_now()
        save_store(path, data)
        snapshot = dict(current)
    return remind_controller(snapshot, age_seconds, last_state)


def decision_fingerprint(decision):
    canonical = json.dumps(
        decision,
        ensure_ascii=False,
        sort_keys=True,
        separators=(
            ",",
            ":",
        ),
    ).encode(
        "utf-8"
    )

    return hashlib.sha256(
        canonical
    ).hexdigest()[:24]


def controller_decision(item):
    request_id = item.get(
        "requestId",
        "",
    )

    if not request_id:
        return None

    url = (
        controller_url()
        + "/decision/"
        + parse.quote(
            request_id,
            safe="",
        )
    )

    journal_controller_event(
        item,
        "CONTROLLER_DECISION_POLLING_STARTED",
        controller_event_key(
            item,
            "decision-polling-started",
            "initial",
        ),
        {
            "endpoint": url,
        },
    )

    status = None

    try:
        with request.urlopen(
            url,
            timeout=(
                CONTROLLER_HTTP_TIMEOUT_SECONDS
            ),
        ) as response:
            note_session_activity("controller")
            status = response.status

            if status == 204:
                journal_controller_event(
                    item,
                    "CONTROLLER_DECISION_NOT_AVAILABLE",
                    controller_event_key(
                        item,
                        "decision-not-available",
                        "first",
                    ),
                    {
                        "endpoint": url,
                        "http_status": status,
                    },
                )

                return None

            if status != 200:
                bucket = int(
                    time.time() // 60
                )

                journal_controller_event(
                    item,
                    "CONTROLLER_DECISION_HTTP_ERROR",
                    controller_event_key(
                        item,
                        "decision-http-error",
                        "%s-%s" % (
                            status,
                            bucket,
                        ),
                    ),
                    {
                        "endpoint": url,
                        "http_status": status,
                    },
                )

                return None

            raw_body = response.read()

    except error.HTTPError as exc:
        status = exc.code

        if status == 404:
            journal_controller_event(
                item,
                "CONTROLLER_DECISION_NOT_AVAILABLE",
                controller_event_key(
                    item,
                    "decision-not-available",
                    "first",
                ),
                {
                    "endpoint": url,
                    "http_status": status,
                },
            )

            return None

        bucket = int(
            time.time() // 60
        )

        journal_controller_event(
            item,
            "CONTROLLER_DECISION_HTTP_ERROR",
            controller_event_key(
                item,
                "decision-http-error",
                "%s-%s" % (
                    status,
                    bucket,
                ),
            ),
            {
                "endpoint": url,
                "http_status": status,
                "error": "HTTPError: %s" % status,
            },
        )

        return None

    except error.URLError as exc:
        failure = "URLError: %s" % exc.reason
        fingerprint = hashlib.sha256(
            failure.encode(
                "utf-8"
            )
        ).hexdigest()[:16]
        bucket = int(
            time.time() // 60
        )

        journal_controller_event(
            item,
            "CONTROLLER_DECISION_TRANSPORT_FAILED",
            controller_event_key(
                item,
                "decision-transport-failed",
                "%s-%s" % (
                    fingerprint,
                    bucket,
                ),
            ),
            {
                "endpoint": url,
                "error": failure,
            },
        )

        return None

    except OSError as exc:
        failure = "OSError: %s" % exc
        fingerprint = hashlib.sha256(
            failure.encode(
                "utf-8"
            )
        ).hexdigest()[:16]
        bucket = int(
            time.time() // 60
        )

        journal_controller_event(
            item,
            "CONTROLLER_DECISION_TRANSPORT_FAILED",
            controller_event_key(
                item,
                "decision-transport-failed",
                "%s-%s" % (
                    fingerprint,
                    bucket,
                ),
            ),
            {
                "endpoint": url,
                "error": failure,
            },
        )

        return None

    if not raw_body:
        fingerprint = "empty-body"

        journal_controller_event(
            item,
            "CONTROLLER_DECISION_INVALID_RESPONSE",
            controller_event_key(
                item,
                "decision-invalid-response",
                fingerprint,
            ),
            {
                "endpoint": url,
                "http_status": status,
                "reason": "reponse vide",
            },
        )

        return None

    try:
        payload = json.loads(
            raw_body.decode(
                "utf-8"
            )
        )

    except (
        UnicodeDecodeError,
        json.JSONDecodeError,
    ) as exc:
        fingerprint = hashlib.sha256(
            raw_body
        ).hexdigest()[:24]

        journal_controller_event(
            item,
            "CONTROLLER_DECISION_INVALID_RESPONSE",
            controller_event_key(
                item,
                "decision-invalid-response",
                fingerprint,
            ),
            {
                "endpoint": url,
                "http_status": status,
                "reason": str(exc),
                "fingerprint": fingerprint,
            },
        )

        return None

    if not isinstance(
        payload,
        dict,
    ):
        fingerprint = decision_fingerprint(
            {
                "payload": payload,
            }
        )

        journal_controller_event(
            item,
            "CONTROLLER_DECISION_INVALID_RESPONSE",
            controller_event_key(
                item,
                "decision-invalid-response",
                fingerprint,
            ),
            {
                "endpoint": url,
                "http_status": status,
                "reason": "objet JSON attendu",
                "fingerprint": fingerprint,
            },
        )

        return None

    if payload.get(
        "decision"
    ) not in (
        "approved",
        "rejected",
        "needs_clarification",
    ):
        fingerprint = decision_fingerprint(
            payload
        )

        journal_controller_event(
            item,
            "CONTROLLER_DECISION_INVALID_RESPONSE",
            controller_event_key(
                item,
                "decision-invalid-response",
                fingerprint,
            ),
            {
                "endpoint": url,
                "http_status": status,
                "reason": "decision absente ou invalide",
                "fingerprint": fingerprint,
            },
        )

        return None

    fingerprint = decision_fingerprint(
        payload
    )

    journal_controller_event(
        item,
        "CONTROLLER_DECISION_RECEIVED",
        controller_event_key(
            item,
            "decision-received",
            fingerprint,
        ),
        {
            "decision_id": payload.get(
                "decision_id",
                "",
            ),
            "decision": payload.get(
                "decision",
                "",
            ),
            "reviewer": payload.get(
                "reviewer",
                "",
            ),
            "fingerprint": fingerprint,
            "http_status": status,
        },
    )

    if not validate_controller_decision(
        item,
        payload,
    ):
        journal_controller_event(
            item,
            (
                "CONTROLLER_DECISION_"
                "REJECTED_CORRELATION"
            ),
            controller_event_key(
                item,
                "decision-rejected-correlation",
                fingerprint,
            ),
            {
                "decision_id": payload.get(
                    "decision_id",
                    "",
                ),
                "decision": payload.get(
                    "decision",
                    "",
                ),
                "returned_approval_id": payload.get(
                    "approval_id",
                    "",
                ),
                "returned_requestId": payload.get(
                    "requestId",
                    "",
                ),
                "returned_change_id": payload.get(
                    "change_id",
                    "",
                ),
                "expected_approval_id": item.get(
                    "approval_id",
                    "",
                ),
                "expected_requestId": item.get(
                    "requestId",
                    "",
                ),
                "expected_change_id": item.get(
                    "change_id",
                    "",
                ),
                "fingerprint": fingerprint,
            },
        )

        return None

    return payload

def validate_controller_decision(
    item,
    decision,
):
    if not isinstance(
        decision,
        dict,
    ):
        return False

    if item.get("run_id") and (decision.get("run_id") != item["run_id"] or
            decision.get("reservation_version") != item.get("reservation_version")):
        return False
    if item.get("coordination_protocol") and any(
        decision.get(key) != item.get(key)
        for key in ("coordination_protocol", "operation_id", "operation_digest", "expected_revisions", "resources", "access_id")
    ):
        return False

    approval_id = item.get(
        "approval_id"
    )

    request_id = item.get(
        "requestId"
    )

    change_id = item.get(
        "change_id"
    )

    decision_approval_id = decision.get(
        "approval_id"
    )

    decision_request_id = decision.get(
        "requestId"
    )

    decision_change_id = decision.get(
        "change_id"
    )

    if (
        not isinstance(
            approval_id,
            str,
        )
        or not approval_id
        or not isinstance(
            request_id,
            str,
        )
        or not request_id
        or not isinstance(
            change_id,
            str,
        )
        or not change_id
    ):
        return False

    if (
        decision_approval_id
        != approval_id
        or decision_request_id
        != request_id
        or decision_change_id
        != change_id
    ):
        return False

    return True


def notification_retry_delay(
    attempts,
):
    if attempts < 1:
        attempts = 1

    delay = (
        NOTIFICATION_RETRY_INITIAL_SECONDS
        * (
            2
            ** (
                attempts - 1
            )
        )
    )

    return min(
        delay,
        NOTIFICATION_RETRY_MAX_SECONDS,
    )


def notification_lease_active(item):
    if item.get(
        "notification_status"
    ) != "SENDING":
        return False

    lease_until = parse_utc(
        item.get(
            "notification_lease_until"
        )
    )

    if lease_until is None:
        return False

    return (
        time.time()
        < lease_until
    )


def notification_retry_due(item):
    if item.get(
        "notification_status"
    ) == "DELIVERED":
        return False

    if notification_lease_active(
        item
    ):
        return False

    retry_at = parse_utc(
        item.get(
            "notification_next_retry_at"
        )
    )

    if retry_at is None:
        return True

    return (
        time.time()
        >= retry_at
    )


def acquire_notification_lease(
    approval_id,
):
    path = store_path()

    with locked_store(
        path
    ):
        data = load_store(
            path
        )

        item = data[
            "approvals"
        ].get(
            approval_id
        )

        if item is None:
            return None

        expired = check_expired(
            item
        )

        if expired:
            save_store(
                path,
                data,
            )

            repair_journal_for_item(
                item
            )

            return None

        if item.get(
            "status"
        ) != "PENDING":
            repair_journal_for_item(
                item
            )

            return None

        if not notification_retry_due(
            item
        ):
            return None

        lease_id = uuid.uuid4().hex

        item[
            "notification_status"
        ] = "SENDING"

        item[
            "notification_lease_id"
        ] = lease_id

        item[
            "notification_lease_until"
        ] = utc_from_timestamp(
            time.time()
            + NOTIFICATION_LEASE_SECONDS
        )

        item[
            "notification_updated_at"
        ] = utc_now()

        save_store(
            path,
            data,
        )

        return {
            "lease_id": lease_id,
            "approval": dict(
                item
            ),
        }


def complete_notification_lease(
    approval_id,
    lease_id,
    delivered,
):
    path = store_path()

    with locked_store(
        path
    ):
        data = load_store(
            path
        )

        item = data[
            "approvals"
        ].get(
            approval_id
        )

        if item is None:
            return

        if item.get(
            "notification_lease_id"
        ) != lease_id:
            return

        attempts = item.get(
            "notification_attempts",
            0,
        )

        if (
            not isinstance(
                attempts,
                int,
            )
            or isinstance(
                attempts,
                bool,
            )
        ):
            attempts = 0

        attempts += 1

        item[
            "notification_attempts"
        ] = attempts

        item[
            "notification_updated_at"
        ] = utc_now()

        item[
            "notification_lease_id"
        ] = ""

        item[
            "notification_lease_until"
        ] = ""

        if delivered:
            item[
                "notification_status"
            ] = "DELIVERED"

            item[
                "notification_next_retry_at"
            ] = ""

        else:
            item[
                "notification_status"
            ] = "FAILED"

            item[
                "notification_next_retry_at"
            ] = utc_from_timestamp(
                time.time()
                + notification_retry_delay(
                    attempts
                )
            )

        save_store(
            path,
            data,
        )


def maybe_notify_controller(item):
    approval_id = item.get(
        "approval_id"
    )

    if not approval_id:
        return False

    lease = acquire_notification_lease(
        approval_id
    )

    if lease is None:
        return False

    notification_result = notify_controller(
        lease[
            "approval"
        ],
        lease[
            "lease_id"
        ],
    )

    delivered = notification_result.get(
        "delivered",
        False,
    )

    complete_notification_lease(
        approval_id,
        lease[
            "lease_id"
        ],
        delivered,
    )

    return delivered


def require_str(
    args,
    name,
    max_len=500,
):
    value = args.get(
        name
    )

    if (
        not isinstance(
            value,
            str,
        )
        or not value.strip()
    ):
        raise ValidationError(
            "parametre '%s' obligatoire et non vide"
            % name
        )

    if len(
        value
    ) > max_len:
        raise ValidationError(
            "parametre '%s' trop long (max %d)"
            % (
                name,
                max_len,
            )
        )

    return value.strip()


def optional_str(
    args,
    name,
    max_len=500,
):
    value = args.get(
        name,
        "",
    )

    if value in (
        None,
        "",
    ):
        return ""

    if not isinstance(
        value,
        str,
    ):
        raise ValidationError(
            "parametre '%s' : chaine attendue"
            % name
        )

    value = value.strip()

    if len(
        value
    ) > max_len:
        raise ValidationError(
            "parametre '%s' trop long (max %d)"
            % (
                name,
                max_len,
            )
        )

    return value


def require_list_str(
    args,
    name,
    max_items=50,
    allow_empty=False,
):
    value = args.get(
        name
    )

    if (
        not isinstance(
            value,
            list,
        )
        or (
            not allow_empty
            and not value
        )
    ):
        raise ValidationError(
            "parametre '%s' : liste non vide obligatoire"
            % name
        )

    if len(
        value
    ) > max_items:
        raise ValidationError(
            "parametre '%s' : trop d elements"
            % name
        )

    result = []

    for entry in value:
        if (
            not isinstance(
                entry,
                str,
            )
            or not entry.strip()
        ):
            raise ValidationError(
                "parametre '%s' : entree vide interdite"
                % name
            )

        result.append(
            entry.strip()
        )

    return result


def validate_unitary_operation(
    args,
):
    operation_args = dict(
        args
    )
    operation_args.setdefault(
        "commands",
        [],
    )

    files = require_list_str(
        operation_args,
        "files",
        max_items=1,
        allow_empty=True,
    )

    commands = require_list_str(
        operation_args,
        "commands",
        max_items=1,
        allow_empty=True,
    )

    if (
        len(files) != 1
        and len(commands) != 1
    ) or (
        files
        and commands
    ):
        raise ValidationError(
            "un mandat doit contenir un fichier ou une commande unique"
        )

    return files, commands


def validate_wait_parameters(
    args,
    default_timeout,
    allow_no_timeout=False,
):
    timeout_seconds = args.get(
        "timeout_seconds",
        default_timeout,
    )

    interval_seconds = args.get(
        "interval_seconds",
        DEFAULT_POLL_INTERVAL_SECONDS,
    )

    if (
        not isinstance(
            timeout_seconds,
            int,
        )
        or isinstance(
            timeout_seconds,
            bool,
        )
    ):
        raise ValidationError(
            "parametre 'timeout_seconds' : entier attendu"
        )

    if allow_no_timeout:
        if (
            timeout_seconds < 0
            or timeout_seconds > 86400
        ):
            raise ValidationError(
                "parametre 'timeout_seconds' : "
                "entier entre 0 et 86400"
            )

    else:
        if (
            timeout_seconds < 1
            or timeout_seconds > 3600
        ):
            raise ValidationError(
                "parametre 'timeout_seconds' : "
                "entier entre 1 et 3600"
            )

    if (
        not isinstance(
            interval_seconds,
            int,
        )
        or isinstance(
            interval_seconds,
            bool,
        )
        or interval_seconds < 1
        or interval_seconds > 60
    ):
        raise ValidationError(
            "parametre 'interval_seconds' : "
            "entier entre 1 et 60"
        )

    return (
        timeout_seconds,
        interval_seconds,
    )


def apply_controller_decision(
    item,
    decision,
):
    if not validate_controller_decision(
        item,
        decision,
    ):
        return False

    decision_value = decision.get(
        "decision"
    )

    if decision_value == "approved":
        status = "APPROVED"

    elif decision_value == "rejected":
        status = "REJECTED"

    elif decision_value == "needs_clarification":
        status = "NEEDS_CLARIFICATION"

    else:
        return False

    now = utc_now()

    item[
        "status"
    ] = status

    item[
        "reviewer"
    ] = decision.get(
        "reviewer",
        "CGPT",
    )

    item[
        "comment"
    ] = decision.get(
        "comment",
        "",
    )

    item[
        "updated_at"
    ] = now

    item[
        "decision_applied_at"
    ] = now

    decision_id = decision.get(
        "decision_id"
    )

    if isinstance(
        decision_id,
        str,
    ):
        item[
            "decision_id"
        ] = decision_id

    return True


def validate_existing_approval(
    item,
    change_id,
    title,
    files,
    request_id,
    session_id,
    directory,
    commands,
    run_identity=None,
):
    if bool(item.get("run_id")) != bool(run_identity):
        return False
    if run_identity and any(item.get(k) != v for k, v in run_identity.items()):
        return False
    if item.get(
        "change_id"
    ) != change_id:
        return False

    if item.get(
        "title"
    ) != title:
        return False

    if item.get(
        "files"
    ) != files:
        return False

    if item.get("session_id", "") != session_id:
        return False

    if item.get("directory", "") != directory:
        return False

    if item.get("commands", []) != commands:
        return False

    if (
        request_id
        and not request_id_matches_item(
            item,
            request_id,
        )
    ):
        return False

    return True


def do_propose(args):
    change_id = require_str(
        args,
        "change_id",
        200,
    )

    title = require_str(
        args,
        "title",
        300,
    )

    files, commands = validate_unitary_operation(
        args,
    )

    summary = optional_str(
        args,
        "summary",
        2000,
    )

    approval_id = optional_str(
        args,
        "approval_id",
        100,
    )

    request_id = optional_str(
        args,
        "requestId",
        100,
    )

    session_id = optional_str(
        args,
        "session_id",
        200,
    )

    directory = optional_str(
        args,
        "directory",
        500,
    )

    run_id = optional_str(args, "run_id", 100)
    run_identity = {}
    if run_id:
        version = args.get("reservation_version")
        resources = args.get("resources", [])
        if (not session_id or not request_id or not approval_id or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", run_id)
                or type(version) is not int or version < 1
                or not isinstance(resources, list) or len(resources) > 256
                or any(not isinstance(r, dict) or r.get("mode") not in ("read", "write")
                       or not isinstance(r.get("key"), str) or not r["key"] or len(r["key"]) > 500
                       for r in resources)):
            raise ValidationError("identite RUN ou ressources invalides")
        if commands and not resources:
            raise ValidationError("ressources explicites requises pour une commande concurrente")
        run_identity = {"run_id": run_id, "reservation_version": version, "resources": resources}
        operation_id = args.get("operation_id")
        operation_digest = args.get("operation_digest")
        expected_revisions = args.get("expected_revisions")
        access_id = args.get("access_id")
        if (args.get("coordination_protocol") != "resource-scoped-v1"
                or not isinstance(operation_id, str)
                or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", operation_id)
                or not isinstance(operation_digest, str)
                or not re.fullmatch(r"[a-f0-9]{64}", operation_digest)
                or not isinstance(expected_revisions, dict)
                or len(expected_revisions) > 256
                or set(expected_revisions) != {r["key"] for r in resources}
                or any(type(value) is not int or value < 0 for value in expected_revisions.values())
                or (access_id is not None and (not isinstance(access_id, str)
                    or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,99}", access_id)))):
            raise ValidationError("protocole de coordination ou identite d operation invalide")
        run_identity.update(coordination_protocol="resource-scoped-v1", operation_id=operation_id,
                            operation_digest=operation_digest, expected_revisions=expected_revisions)
        if access_id is not None:
            run_identity["access_id"] = access_id
    elif any(key in args for key in ("reservation_version", "resources", "coordination_protocol",
                                     "operation_id", "operation_digest", "expected_revisions", "access_id")):
        raise ValidationError("run_id requis pour la reservation")

    if bool(session_id) != bool(directory):
        raise ValidationError(
            "session_id et directory doivent etre fournis ensemble"
        )

    if session_id:
        if not session_id.startswith("ses_"):
            raise ValidationError("parametre 'session_id' invalide")

        if not directory.startswith("/"):
            raise ValidationError("parametre 'directory' invalide")

        if any(
            path.startswith("/")
            or path == ".."
            or path.startswith("../")
            for path in files
        ):
            raise ValidationError(
                "files doit contenir des chemins relatifs sans remontee"
            )

    ttl = args.get(
        "ttl_seconds",
        DEFAULT_TTL_SECONDS,
    )

    if (
        not isinstance(
            ttl,
            int,
        )
        or isinstance(
            ttl,
            bool,
        )
        or ttl < 60
        or ttl > 604800
    ):
        raise ValidationError(
            "parametre 'ttl_seconds' : "
            "entier entre 60 et 604800"
        )

    path = store_path()
    should_notify = False

    with locked_store(
        path
    ):
        data = load_store(
            path
        )

        approvals = data[
            "approvals"
        ]

        unique, duplicate = (
            check_request_id_uniqueness(
                approvals
            )
        )

        if not unique:
            raise StoreError(
                "requestId duplique : %s"
                % duplicate
            )

        existing = None

        if approval_id:
            existing = approvals.get(
                approval_id
            )

        if (
            existing is None
            and request_id
        ):
            request_match = find_by_request_id(
                approvals,
                request_id,
            )

            if request_match is not None:
                if (
                    approval_id
                    and request_match.get(
                        "approval_id"
                    )
                    != approval_id
                ):
                    raise ValidationError(
                        "requestId '%s' appartient deja "
                        "a approval_id '%s'"
                        % (
                            request_id,
                            request_match.get(
                                "approval_id"
                            ),
                        )
                    )

                existing = request_match

                approval_id = existing.get(
                    "approval_id"
                )

        if existing is not None:
            expired = check_expired(
                existing
            )

            if expired:
                save_store(
                    path,
                    data,
                )

            repair_journal_for_item(
                existing
            )

            if not validate_existing_approval(
                existing,
                change_id,
                title,
                files,
                request_id,
                session_id,
                directory,
                commands,
                run_identity,
            ):
                raise ValidationError(
                    "retry incompatible avec "
                    "l'approbation '%s'"
                    % existing.get(
                        "approval_id"
                    )
                )

            should_notify = (
                existing.get(
                    "status"
                )
                == "PENDING"
                and notification_retry_due(
                    existing
                )
            )

            result = dict(
                existing
            )

        else:
            if not request_id:
                request_id = (
                    new_business_request_id()
                )

            while (
                find_by_request_id(
                    approvals,
                    request_id,
                )
                is not None
            ):
                request_id = (
                    new_business_request_id()
                )

            if not approval_id:
                approval_id = (
                    new_approval_id()
                )

                while approval_id in approvals:
                    approval_id = (
                        new_approval_id()
                    )

            elif approval_id in approvals:
                raise ValidationError(
                    "approval_id '%s' deja utilise"
                    % approval_id
                )

            now = utc_now()

            item = {
                **run_identity,
                "approval_id": approval_id,
                "requestId": request_id,
                "legacy_requestIds": [],
                "change_id": change_id,
                "title": title,
                "files": files,
                "session_id": session_id,
                "directory": directory,
                "commands": commands,
                "summary": summary,
                "status": "PENDING",
                "requester": "OC",
                "reviewer": "",
                "comment": "",
                "created_at": now,
                "updated_at": now,
                "expires_at": (
                    utc_from_timestamp(
                        time.time()
                        + ttl
                    )
                ),
                "notification_status": "PENDING",
                "notification_attempts": 0,
                "notification_updated_at": "",
                "notification_next_retry_at": "",
                "notification_lease_id": "",
                "notification_lease_until": "",
                "reminder_last_at": "",
                "decision_id": "",
                "decision_applied_at": "",
                "cancelled_at": "",
                "cancelled_by": "",
                "expired_at": "",
            }

            approvals[
                approval_id
            ] = item

            save_store(
                path,
                data,
            )

            ensure_created_event(
                item
            )

            result = dict(
                item
            )

            should_notify = True

    if should_notify:
        maybe_notify_controller(
            result
        )

        with locked_store(
            path
        ):
            data = load_store(
                path
            )

            current = data[
                "approvals"
            ].get(
                approval_id
            )

            if current is not None:
                result = dict(
                    current
                )

    return result


def do_get(args):
    approval_id = optional_str(
        args,
        "approval_id",
        100,
    )

    path = store_path()

    should_notify = False
    should_check_decision = False

    with locked_store(
        path
    ):
        data = load_store(
            path
        )

        item = data[
            "approvals"
        ].get(
            approval_id
        )

        if item is None:
            raise ValidationError(
                "approval_id '%s' inconnu"
                % approval_id
            )

        expired = check_expired(
            item
        )

        if expired:
            save_store(
                path,
                data,
            )

        repair_journal_for_item(
            item
        )

        if item.get(
            "status"
        ) == "PENDING":
            should_check_decision = True

            should_notify = (
                notification_retry_due(
                    item
                )
            )

        snapshot = dict(
            item
        )

    if should_notify:
        maybe_notify_controller(
            snapshot
        )

    decision = None

    if should_check_decision:
        decision = controller_decision(
            snapshot
        )

    with locked_store(
        path
    ):
        data = load_store(
            path
        )

        item = data[
            "approvals"
        ].get(
            approval_id
        )

        if item is None:
            raise ValidationError(
                "approval_id '%s' inconnu"
                % approval_id
            )

        changed = check_expired(
            item
        )

        if (
            decision is not None
            and item.get(
                "status"
            )
            == "PENDING"
        ):
            if apply_controller_decision(
                item,
                decision,
            ):
                changed = True

        if changed:
            save_store(
                path,
                data,
            )

        repair_journal_for_item(
            item
        )

        return dict(
            item
        )


def wait_for_approval(
    approval_id,
    timeout_seconds,
    interval_seconds,
    timeout_kind,
    cancel_event=None,
):
    deadline = None

    if timeout_seconds > 0:
        deadline = (
            time.monotonic()
            + timeout_seconds
        )

    while True:
        if (
            cancel_event is not None
            and cancel_event.is_set()
        ):
            raise RequestCancelled()

        item = do_get(
            {
                "approval_id": approval_id,
            }
        )

        if item.get(
            "status"
        ) in TERMINAL_STATES:
            return item

        if (
            deadline is not None
            and time.monotonic()
            >= deadline
        ):
            result = dict(
                item
            )

            result[
                timeout_kind
            ] = True

            result[
                "retry_required"
            ] = True

            result[
                "next_action"
            ] = "poll_approval"

            result[
                "retry_approval_id"
            ] = approval_id

            return result

        if cancel_event is not None:
            if cancel_event.wait(
                interval_seconds
            ):
                raise RequestCancelled()

        else:
            time.sleep(
                interval_seconds
            )


def do_poll(
    args,
    cancel_event=None,
):
    approval_id = require_str(
        args,
        "approval_id",
        100,
    )

    (
        timeout_seconds,
        interval_seconds,
    ) = validate_wait_parameters(
        args,
        DEFAULT_POLL_TIMEOUT_SECONDS,
        allow_no_timeout=False,
    )

    return wait_for_approval(
        approval_id,
        timeout_seconds,
        interval_seconds,
        "poll_timeout",
        cancel_event=cancel_event,
    )


def do_request_validation(
    args,
    cancel_event=None,
):
    (
        timeout_seconds,
        interval_seconds,
    ) = validate_wait_parameters(
        args,
        DEFAULT_REQUEST_TIMEOUT_SECONDS,
        allow_no_timeout=True,
    )

    item = do_propose(
        args
    )

    if item.get(
        "status"
    ) in TERMINAL_STATES:
        return item

    return wait_for_approval(
        item[
            "approval_id"
        ],
        timeout_seconds,
        interval_seconds,
        "validation_timeout",
        cancel_event=cancel_event,
    )


def do_list(args):
    status = args.get(
        "status",
        "",
    )

    if (
        status
        and status not in VALID_STATES
    ):
        raise ValidationError(
            "status inconnu, attendu parmi %s"
            % ",".join(
                VALID_STATES
            )
        )

    limit = args.get(
        "limit",
        50,
    )

    if (
        not isinstance(
            limit,
            int,
        )
        or isinstance(
            limit,
            bool,
        )
        or limit < 1
        or limit > 200
    ):
        raise ValidationError(
            "parametre 'limit' : "
            "entier entre 1 et 200"
        )

    path = store_path()

    with locked_store(
        path
    ):
        data = load_store(
            path
        )

        changed = False

        for item in data[
            "approvals"
        ].values():
            if check_expired(
                item
            ):
                changed = True

        #
        # Important :
        # toutes les expirations sont persistantes
        # AVANT leur journalisation.
        #
        if changed:
            save_store(
                path,
                data,
            )

        items = []

        event_index = {
            (event.get("approval_id", ""), event.get("event_type", ""))
            for event in journal.read_events()
        } if data["approvals"] else set()

        for item in data[
            "approvals"
        ].values():
            repair_journal_for_item(
                item,
                event_index=event_index,
            )

            if (
                not status
                or item.get(
                    "status"
                )
                == status
            ):
                items.append(
                    dict(
                        item
                    )
                )

    items.sort(
        key=lambda value: value.get(
            "created_at",
            "",
        )
    )

    return {
        "approvals": items[:limit],
        "count": len(
            items
        ),
    }


def do_decide(
    args,
    decision,
):
    approval_id = require_str(
        args,
        "approval_id",
        100,
    )

    reviewer = require_str(
        args,
        "reviewer",
        100,
    )

    comment = optional_str(
        args,
        "comment",
        2000,
    )

    path = store_path()

    with locked_store(
        path
    ):
        data = load_store(
            path
        )

        item = data[
            "approvals"
        ].get(
            approval_id
        )

        if item is None:
            raise ValidationError(
                "approval_id '%s' inconnu"
                % approval_id
            )

        expired = check_expired(
            item
        )

        if expired:
            save_store(
                path,
                data,
            )

            repair_journal_for_item(
                item
            )

        if item.get(
            "status"
        ) not in DECIDABLE:
            if item.get(
                "status"
            ) == decision:
                repair_journal_for_item(
                    item
                )

                return dict(
                    item
                )

            raise ValidationError(
                "decision refusee : "
                "statut '%s' non decidable"
                % item.get(
                    "status"
                )
            )

        now = utc_now()

        item[
            "status"
        ] = decision

        item[
            "reviewer"
        ] = reviewer

        item[
            "comment"
        ] = comment

        item[
            "updated_at"
        ] = now

        item[
            "decision_applied_at"
        ] = now

        save_store(
            path,
            data,
        )

        repair_journal_for_item(
            item
        )

        return dict(
            item
        )


def do_cancel(args):
    approval_id = require_str(
        args,
        "approval_id",
        100,
    )

    path = store_path()

    with locked_store(
        path
    ):
        data = load_store(
            path
        )

        item = data[
            "approvals"
        ].get(
            approval_id
        )

        if item is None:
            raise ValidationError(
                "approval_id '%s' inconnu"
                % approval_id
            )

        expired = check_expired(
            item
        )

        if expired:
            save_store(
                path,
                data,
            )

            repair_journal_for_item(
                item
            )

        if item.get(
            "status"
        ) == "CANCELLED":
            repair_journal_for_item(
                item
            )

            return dict(
                item
            )

        if item.get(
            "status"
        ) not in DECIDABLE:
            raise ValidationError(
                "annulation refusee : "
                "statut '%s' non annulable"
                % item.get(
                    "status"
                )
            )

        now = utc_now()

        item[
            "status"
        ] = "CANCELLED"

        item[
            "updated_at"
        ] = now

        item[
            "cancelled_at"
        ] = now

        item[
            "cancelled_by"
        ] = "OC"

        save_store(
            path,
            data,
        )

        repair_journal_for_item(
            item
        )

        return dict(
            item
        )


def control_increment():
    global CONTROL_INFLIGHT

    with CONTROL_STATE_LOCK:
        CONTROL_INFLIGHT += 1


def control_decrement():
    global CONTROL_INFLIGHT

    with CONTROL_STATE_LOCK:
        if CONTROL_INFLIGHT > 0:
            CONTROL_INFLIGHT -= 1


def fast_increment():
    global FAST_INFLIGHT

    with FAST_STATE_LOCK:
        FAST_INFLIGHT += 1


def fast_decrement():
    global FAST_INFLIGHT

    with FAST_STATE_LOCK:
        if FAST_INFLIGHT > 0:
            FAST_INFLIGHT -= 1


def blocking_increment():
    global BLOCKING_INFLIGHT

    with BLOCKING_STATE_LOCK:
        BLOCKING_INFLIGHT += 1


def blocking_decrement():
