                "reviewer",
            ],
        },
    },
    {
        "name": "cancel_approval",
        "description": (
            "Annule une approbation PENDING."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "approval_id": {
                    "type": "string",
                },
            },
            "required": [
                "approval_id",
            ],
        },
    },
]


def ok_result(
    request_id,
    result,
):
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "result": result,
    }


def ok_tools_call(payload):
    return {
        "content": [
            {
                "type": "text",
                "text": json.dumps(
                    payload,
                    ensure_ascii=False,
                ),
            }
        ],
    }


def err_result(
    request_id,
    code,
    message,
):
    return {
        "jsonrpc": "2.0",
        "id": request_id,
        "error": {
            "code": code,
            "message": message,
        },
    }


def valid_jsonrpc_id(value):
    if value is None:
        return True

    if isinstance(
        value,
        bool,
    ):
        return False

    return isinstance(
        value,
        (
            str,
            int,
            float,
        ),
    )


def validate_jsonrpc_message(message):
    if not isinstance(
        message,
        dict,
    ):
        return (
            False,
            err_result(
                None,
                -32600,
                "Invalid Request: objet JSON attendu",
            ),
        )

    if message.get(
        "jsonrpc"
    ) != "2.0":
        request_id = message.get(
            "id"
        )

        if not valid_jsonrpc_id(
            request_id
        ):
            request_id = None

        return (
            False,
            err_result(
                request_id,
                -32600,
                "jsonrpc doit valoir '2.0'",
            ),
        )

    method = message.get(
        "method"
    )

    if (
        not isinstance(
            method,
            str,
        )
        or not method
    ):
        return (
            False,
            err_result(
                message.get(
                    "id"
                ),
                -32600,
                "method invalide",
            ),
        )

    if (
        "id" in message
        and not valid_jsonrpc_id(
            message.get(
                "id"
            )
        )
    ):
        return (
            False,
            err_result(
                None,
                -32600,
                "id JSON-RPC invalide",
            ),
        )

    if (
        "params" in message
        and message[
            "params"
        ] is not None
        and not isinstance(
            message[
                "params"
            ],
            dict,
        )
    ):
        return (
            False,
            err_result(
                message.get(
                    "id"
                ),
                -32602,
                "params doit etre un objet",
            ),
        )

    return (
        True,
        None,
    )


def is_notification(req):
    return (
        isinstance(
            req,
            dict,
        )
        and "id" not in req
    )


def validate_mcp_request(req):
    method = req.get(
        "method"
    )

    if is_notification(
        req
    ):
        if method in KNOWN_NOTIFICATIONS:
            return (
                True,
                None,
            )

        return (
            False,
            None,
        )

    if method in KNOWN_NOTIFICATIONS:
        return (
            False,
            err_result(
                req.get(
                    "id"
                ),
                -32600,
                "notification avec id interdite",
            ),
        )

    if method == "tools/call":
        params = (
            req.get(
                "params"
            )
            or {}
        )

        name = params.get(
            "name"
        )

        if (
            not isinstance(
                name,
                str,
            )
            or not name
        ):
            return (
                False,
                err_result(
                    req.get(
                        "id"
                    ),
                    -32602,
                    "tools/call name obligatoire",
                ),
            )

        arguments = params.get(
            "arguments",
            {},
        )

        if (
            arguments is not None
            and not isinstance(
                arguments,
                dict,
            )
        ):
            return (
                False,
                err_result(
                    req.get(
                        "id"
                    ),
                    -32602,
                    "arguments doit etre un objet",
                ),
            )

    return (
        True,
        None,
    )


def register_active_request(
    request_id,
):
    if request_id is None:
        return None

    event = threading.Event()

    with ACTIVE_REQUESTS_LOCK:
        if request_id in ACTIVE_REQUESTS:
            raise DuplicateRequestId(
                "id JSON-RPC deja actif : %s"
                % request_id
            )

        ACTIVE_REQUESTS[
            request_id
        ] = event

    return event


def unregister_active_request(
    request_id,
    event,
):
    if (
        request_id is None
        or event is None
    ):
        return

    with ACTIVE_REQUESTS_LOCK:
        if (
            ACTIVE_REQUESTS.get(
                request_id
            )
            is event
        ):
            ACTIVE_REQUESTS.pop(
                request_id,
                None,
            )


def cancel_active_request(
    request_id,
):
    if request_id is None:
        return False

    with ACTIVE_REQUESTS_LOCK:
        event = ACTIVE_REQUESTS.get(
            request_id
        )

    if event is None:
        return False

    event.set()

    return True


def handle_cancel_notification(req):
    params = (
        req.get(
            "params"
        )
        or {}
    )

    request_id = params.get(
        "requestId"
    )

    if (
        request_id is None
        or not valid_jsonrpc_id(
            request_id
        )
    ):
        return False

    return cancel_active_request(
        request_id
    )


def handle_notification(req):
    if req.get(
        "method"
    ) == "notifications/cancelled":
        handle_cancel_notification(
            req
        )


def handle_request(
    req,
    cancel_event=None,
):
    jsonrpc_id = req.get(
        "id"
    )

    method = req.get(
        "method"
    )

    params = (
        req.get(
            "params"
        )
        or {}
    )

    try:
        if method == "initialize":
            return ok_result(
                jsonrpc_id,
                {
                    "protocolVersion": (
                        MCP_PROTOCOL_VERSION
                    ),
                    "capabilities": {
                        "tools": {
                            "listChanged": False,
                        },
                    },
                    "serverInfo": {
                        "name": SERVER_NAME,
                        "version": SERVER_VERSION,
                    },
                },
            )

        if method == "ping":
            return ok_result(
                jsonrpc_id,
                {},
            )

        if method == "tools/list":
            return ok_result(
                jsonrpc_id,
                {
                    "tools": TOOLS,
                },
            )

        if method != "tools/call":
            return err_result(
                jsonrpc_id,
                -32601,
                "methode inconnue : %s"
                % method,
            )

        name = params.get(
            "name"
        )

        args = (
            params.get(
                "arguments"
            )
            or {}
        )

        if name == "request_validation":
            payload = do_request_validation(
                args,
                cancel_event,
            )

        elif name == "poll_approval":
            payload = do_poll(
                args,
                cancel_event,
            )

        elif name == "propose_approval":
            payload = do_propose(
                args
            )

        elif name == "get_approval":
            payload = do_get(
                args
            )

        elif name == "list_pending":
            payload = do_list(
                args
            )

        elif name == "broker_health":
            payload = do_health()

        elif name == "broker_readiness":
            payload = do_readiness(args)

        elif name == "broker_remediation_registry":
            payload = do_remediation_registry(args)

        elif name == "broker_start_remediation_attempt":
            payload = do_start_remediation_attempt(args)

        elif name == "broker_complete_remediation_attempt":
            payload = do_finish_remediation_attempt(args, True)

        elif name == "broker_fail_remediation_attempt":
            payload = do_finish_remediation_attempt(args, False)

        elif name == "broker_auto_remediation_policy":
            payload = auto_remediation_policy_snapshot()

        elif name == "broker_execute_controlled_remediation":
            payload = do_execute_controlled_remediation(args)

        elif name == "broker_evaluate_remediation":
            payload = do_evaluate_remediation(args)

        elif name == "broker_repair_consistency":
            payload = do_repair_consistency()

        elif name == "broker_rotate_journal_checkpoint":
            payload = journal.rotate_checkpoint()

        elif name == "approve":
            payload = do_decide(
                args,
                "APPROVED",
            )

        elif name == "reject":
            payload = do_decide(
                args,
                "REJECTED",
            )

        elif name == "cancel_approval":
            payload = do_cancel(
                args
            )

        else:
            return err_result(
                jsonrpc_id,
                -32601,
                "outil inconnu : %s"
                % name,
            )

        return ok_result(
            jsonrpc_id,
            ok_tools_call(
                payload
            ),
        )

    except RequestCancelled:
        raise

    except ValidationError as exc:
        return err_result(
            jsonrpc_id,
            -32602,
            str(
                exc
            ),
        )

    except StoreError as exc:
        return err_result(
            jsonrpc_id,
            -32000,
            str(
                exc
            ),
        )

    except (
        journal.JournalError,
        journal.JournalValidationError,
    ) as exc:
        return err_result(
            jsonrpc_id,
            -32002,
            "journal : %s"
            % exc,
        )

    except Exception as exc:
        return err_result(
            jsonrpc_id,
            -32603,
            "erreur interne : %s"
            % exc,
        )


def write_response(response):
    if response is None:
        return

    note_session_activity("mcp")

    payload = (
        json.dumps(
            response,
            ensure_ascii=False,
        )
        + "\n"
    )

    with OUTPUT_LOCK:
        sys.stdout.write(
            payload
        )

        sys.stdout.flush()


def process_request(
    req,
    cancel_event,
):
    jsonrpc_id = req.get(
        "id"
    )

    response = None
    cancelled = False

    try:
        response = handle_request(
            req,
            cancel_event,
        )

    except RequestCancelled:
        cancelled = True

    except Exception as exc:
        response = err_result(
            jsonrpc_id,
            -32603,
            "erreur worker : %s"
            % exc,
        )

    finally:
        if (
            cancel_event is not None
            and cancel_event.is_set()
        ):
            cancelled = True

        unregister_active_request(
            jsonrpc_id,
            cancel_event,
        )

    if not cancelled:
        write_response(
            response
        )


def process_control_request(
    req,
    cancel_event,
):
    try:
        process_request(
            req,
            cancel_event,
        )

    finally:
        control_decrement()
        CONTROL_CAPACITY.release()


def process_fast_request(
    req,
    cancel_event,
):
    try:
        process_request(
            req,
            cancel_event,
        )

    finally:
        fast_decrement()
        FAST_CAPACITY.release()


def process_blocking_request(
    req,
    cancel_event,
):
    try:
        process_request(
            req,
            cancel_event,
        )

    finally:
        blocking_decrement()
        BLOCKING_CAPACITY.release()


def tool_name_from_request(req):
    if (
        not isinstance(
            req,
            dict,
        )
        or req.get(
            "method"
        )
        != "tools/call"
    ):
        return ""

    params = (
        req.get(
            "params"
        )
        or {}
    )

    name = params.get(
        "name",
        "",
    )

    return (
        name
        if isinstance(
            name,
            str,
        )
        else ""
    )


def is_direct_control_request(req):
    return (
        isinstance(
            req,
            dict,
        )
        and req.get(
            "method"
        )
        in DIRECT_CONTROL_METHODS
    )


def cancel_all_active_requests():
    with ACTIVE_REQUESTS_LOCK:
        events = list(
            ACTIVE_REQUESTS.values()
        )

    for event in events:
        event.set()


def reject_busy_request(
    jsonrpc_id,
    queue_name,
):
    return err_result(
        jsonrpc_id,
        -32001,
        "capacite maximale du pool %s atteinte"
        % queue_name,
    )


def reject_duplicate_request(
    jsonrpc_id,
):
    return err_result(
        jsonrpc_id,
        -32600,
        "id JSON-RPC deja actif : %s"
        % jsonrpc_id,
    )


def submit_control_request(
    executor,
    req,
):
    jsonrpc_id = req.get(
        "id"
    )

    if not CONTROL_CAPACITY.acquire(
        blocking=False
    ):
        write_response(
            reject_busy_request(
                jsonrpc_id,
                "CONTROL",
            )
        )

        return

    try:
        cancel_event = register_active_request(
            jsonrpc_id
        )

    except DuplicateRequestId:
        CONTROL_CAPACITY.release()

        write_response(
            reject_duplicate_request(
                jsonrpc_id
            )
        )

        return

    control_increment()

    try:
        executor.submit(
            process_control_request,
            req,
            cancel_event,
        )

    except Exception:
        control_decrement()

        unregister_active_request(
            jsonrpc_id,
            cancel_event,
        )

        CONTROL_CAPACITY.release()

        raise


def submit_fast_request(
    executor,
    req,
):
    jsonrpc_id = req.get(
        "id"
    )

    if not FAST_CAPACITY.acquire(
        blocking=False
    ):
        write_response(
            reject_busy_request(
                jsonrpc_id,
                "FAST",
            )
        )

        return

    try:
        cancel_event = register_active_request(
            jsonrpc_id
        )

    except DuplicateRequestId:
        FAST_CAPACITY.release()

        write_response(
            reject_duplicate_request(
                jsonrpc_id
            )
        )

        return

    fast_increment()

    try:
        executor.submit(
            process_fast_request,
            req,
            cancel_event,
        )

    except Exception:
        fast_decrement()

        unregister_active_request(
            jsonrpc_id,
            cancel_event,
        )

        FAST_CAPACITY.release()

        raise


def submit_blocking_request(
    executor,
    req,
):
    jsonrpc_id = req.get(
        "id"
    )

    if not BLOCKING_CAPACITY.acquire(
        blocking=False
    ):
        write_response(
            reject_busy_request(
                jsonrpc_id,
                "BLOCKING",
            )
        )

        return

    try:
        cancel_event = register_active_request(
            jsonrpc_id
        )

    except DuplicateRequestId:
        BLOCKING_CAPACITY.release()

        write_response(
            reject_duplicate_request(
                jsonrpc_id
            )
        )

        return

    blocking_increment()

    try:
        executor.submit(
            process_blocking_request,
            req,
            cancel_event,
        )

    except Exception:
        blocking_decrement()

        unregister_active_request(
            jsonrpc_id,
            cancel_event,
        )

        BLOCKING_CAPACITY.release()

        raise


def main():
    global PROCESS_STARTED_AT

    PROCESS_STARTED_AT = utc_now()

    try:
        acquire_instance_lock()
    except InstanceLockError as exc:
        print(
            "cgpt-approval-bridge: %s"
            % exc,
            file=sys.stderr,
            flush=True,
        )
        return 73

    try:
        journal_instance_started()
    except (
        journal.JournalError,
        journal.JournalValidationError,
    ) as exc:
        print(
            "cgpt-approval-bridge: journalisation demarrage impossible: %s"
            % exc,
            file=sys.stderr,
            flush=True,
        )
        release_instance_lock()
        return 74

    try:
        recover_after_unclean_shutdown()
    except (
        StoreError,
        ValidationError,
        journal.JournalError,
        journal.JournalValidationError,
    ) as exc:
        print(
            "cgpt-approval-bridge: recuperation post-crash impossible: %s"
            % exc,
            file=sys.stderr,
            flush=True,
        )
        release_instance_lock()
        return 75

    try:
        recover_orphaned_remediation_attempts()
    except (
        StoreError,
        ValidationError,
        journal.JournalError,
        journal.JournalValidationError,
    ) as exc:
        print(
            "cgpt-approval-bridge: recuperation remediation orpheline impossible: %s"
            % exc,
            file=sys.stderr,
            flush=True,
        )
        release_instance_lock()
        return 76

    try:
        load_auto_remediation_circuit_state()
    except (
        StoreError,
        journal.JournalError,
        journal.JournalValidationError,
    ) as exc:
        print(
            "cgpt-approval-bridge: restauration circuit breaker impossible: %s"
            % exc,
            file=sys.stderr,
            flush=True,
        )
        release_instance_lock()
        return 77

    control_executor = ThreadPoolExecutor(
        max_workers=MAX_CONTROL_WORKERS,
        thread_name_prefix="cgpt-mcp-control",
    )

    fast_executor = ThreadPoolExecutor(
        max_workers=MAX_FAST_WORKERS,
        thread_name_prefix="cgpt-mcp-fast",
    )

    blocking_executor = ThreadPoolExecutor(
        max_workers=MAX_BLOCKING_WORKERS,
        thread_name_prefix="cgpt-mcp-blocking",
    )

    start_background_reconciliation()
    start_pending_watchdog()
    start_session_watchdog()
    start_readiness_publisher()
    start_auto_remediation_scheduler()

    try:
        for line in sys.stdin:
            line = line.strip()

            if not line:
                continue

            note_session_activity("mcp")

            try:
                req = json.loads(
                    line
                )

            except json.JSONDecodeError:
                write_response(
                    err_result(
                        None,
                        -32700,
                        "Parse error: JSON invalide",
                    )
                )

                continue

            valid, response = (
                validate_jsonrpc_message(
                    req
                )
            )

            if not valid:
                if response is not None:
                    write_response(
                        response
                    )

                continue

            valid, response = (
                validate_mcp_request(
                    req
                )
            )

            if not valid:
                if response is not None:
                    write_response(
                        response
                    )

                continue

            if is_notification(
                req
            ):
                handle_notification(
                    req
                )

                continue

            if is_direct_control_request(
                req
            ):
                write_response(
                    handle_request(
                        req
                    )
                )

                continue

            tool_name = tool_name_from_request(
                req
            )

            if tool_name in CONTROL_TOOLS:
                submit_control_request(
                    control_executor,
                    req,
                )

                continue

            if tool_name in BLOCKING_TOOLS:
                submit_blocking_request(
                    blocking_executor,
                    req,
                )

                continue

            submit_fast_request(
                fast_executor,
                req,
            )

    finally:
        stop_auto_remediation_scheduler()
        stop_readiness_publisher()
        stop_session_watchdog()
        stop_pending_watchdog()
        try:
            journal_instance_stopping()
        except (
            journal.JournalError,
            journal.JournalValidationError,
        ) as exc:
            print(
                "cgpt-approval-bridge: journalisation arret en cours impossible: %s"
                % exc,
                file=sys.stderr,
                flush=True,
            )

        cancel_all_active_requests()

        control_executor.shutdown(
            wait=True,
            cancel_futures=False,
        )

        fast_executor.shutdown(
            wait=True,
            cancel_futures=False,
        )

        blocking_executor.shutdown(
            wait=True,
            cancel_futures=False,
        )

        try:
            journal_instance_stopped()
        except (
            journal.JournalError,
            journal.JournalValidationError,
        ) as exc:
            print(
                "cgpt-approval-bridge: journalisation arret final impossible: %s"
                % exc,
                file=sys.stderr,
                flush=True,
            )

        release_instance_lock()

    return 0


if __name__ == "__main__":
    sys.exit(main())

