      OC_Codex_OPENCODE_URL: `http://127.0.0.1:${opencode.address().port}` },
    stdio: "ignore",
  });
  context.after(async () => {
    const stopped = new Promise((resolve) => controller.once("exit", resolve));
    controller.kill("SIGTERM");
    await stopped;
