  if (strictCommands) {
    permissions.push({
      id: "permission-command-repeat",
      sessionID: "ses_command_test",
      permission: "bash",
      metadata: { command: "printf approved" },
    });
    await delay(150);
    assert.equal(replies.length, 1);
  }
}

for (const strictCommands of [false, true]) {
